cd /workspace && node -e "
const db = require('better-sqlite3')('world.db', {readonly: true});

// Get the booking
const booking = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'BK-B70889'\").get();
console.log('=== BOOKING BK-B70889 ===');
console.log(JSON.stringify(booking, null, 2));

// Get the user
if (booking) {
  const user = db.prepare('SELECT * FROM users WHERE user_id = ?').get(booking.user_id);
  console.log('\n=== USER ===');
  console.log(JSON.stringify(user, null, 2));

  // Get the flight
  if (booking.flight_id) {
    const flight = db.prepare('SELECT * FROM flights WHERE flight_id = ?').get(booking.flight_id);
    console.log('\n=== FLIGHT ===');
    console.log(JSON.stringify(flight, null, 2));
  }
}
"

cd /workspace && node -e "
const db = require('better-sqlite3')('world.db', {readonly: true});

// Search for JFK -> LHR flights
const flights = db.prepare(\"SELECT * FROM flights WHERE origin = 'JFK' AND destination = 'LHR'\").all();
console.log('=== All JFK → LHR Flights ===');
flights.forEach(f => {
  console.log(JSON.stringify({
    flight_id: f.flight_id,
    departure: f.departure_time,
    arrival: f.arrival_time,
    status: f.status,
    cabin_prices: JSON.parse(f.cabin_prices_json),
    dates: JSON.parse(f.dates_json)
  }, null, 2));
  console.log('---');
});

// Also search broadly for any flight with Oct 16 in dates
const allFlights = db.prepare(\"SELECT * FROM flights WHERE origin = 'JFK' AND destination = 'LHR' AND dates_json LIKE '%2026-10-16%'\").all();
console.log('\n=== Flights with Oct 16 availability ===');
console.log(allFlights.length, 'found');
allFlights.forEach(f => console.log(JSON.stringify(f, null, 2)));
"

